// Synthetic only. Fixed lead so a second run can approve the draft made between runs.
const base = 'https://rapower.app.n8n.cloud/webhook/';
const lead = { name: 'Synthetic Http Buyer', email: 'synthetic.http.d8@example.com', phone: '555-0110', source: 'pg-test-http', message: 'Synthetic http inquiry: two bedroom condo. Test data only.' };
const leadKey = lead.email + '|' + lead.message.toLowerCase().slice(0, 80);
const cases = [
  { case: 'A1', mode: 'key', url: base + 'pg-inquiry-intake', payload: lead, note: 'valid lead: run1 200 received, run2 200 duplicate_ignored' },
  { case: 'A2', mode: 'key', url: base + 'pg-draft-decision', payload: { lead_key: leadKey, decision: 'maybe', note: 'bad' }, note: 'invalid decision: expect 400' },
  { case: 'A3', mode: 'key', url: base + 'pg-draft-decision', payload: { lead_key: 'synthetic.nobody@example.com|none', decision: 'approve', note: 'unknown' }, note: 'unknown lead: expect 404' },
  { case: 'A4', mode: 'key', url: base + 'pg-draft-decision', payload: { lead_key: leadKey, decision: 'approve', note: 'Synthetic http approve' }, note: 'run1 404 (no draft yet), run2 200 approved_not_sent' },
  { case: 'B1', mode: 'nokey', url: base + 'pg-inquiry-intake', payload: lead, note: 'no key intake: expect 403' },
  { case: 'B2', mode: 'nokey', url: base + 'pg-draft-decision', payload: { lead_key: leadKey, decision: 'approve', note: 'x' }, note: 'no key decision: expect 403' },
  { case: 'C1', mode: 'wrong', url: base + 'pg-inquiry-intake', payload: lead, note: 'wrong key intake: expect 403' },
  { case: 'C2', mode: 'wrong', url: base + 'pg-draft-decision', payload: { lead_key: leadKey, decision: 'approve', note: 'x' }, note: 'wrong key decision: expect 403' }
];
return cases.map(function (c) { return { json: c }; });

const all = $('Synthetic cases').all().map(function (i) { return i.json; });
const sets = { key: $('Send with key').all().map(function (i) { return i.json; }), nokey: $('Send without key').all().map(function (i) { return i.json; }), wrong: $('Send wrong key').all().map(function (i) { return i.json; }) };
const used = { key: 0, nokey: 0, wrong: 0 };
return all.map(function (c) {
  const res = sets[c.mode][used[c.mode]++];
  let body = res ? res.body : undefined;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
  const status = body && body.status ? body.status : '';
  return { json: { case: c.case, note: c.note, got_code: res ? res.statusCode : null, got_status: status } };
});
